from unittest import TestCase
from unittest.mock import patch

from django.test import SimpleTestCase, ignore_warnings, override_settings


class TestNumberFormat(SimpleTestCase):
    """Test suite for django.utils.numberformat.format function."""

    def setUp(self):
        from django.utils.numberformat import format as nf_format
        self.format = nf_format

    # Test basic integer formatting
    @ignore_warnings(category=DeprecationWarning)
    def test_format_integer_no_decimal_pos(self):
        """Test formatting an integer without decimal position."""
        result = self.format(1234, ".")
        self.assertEqual(result, "1234")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_integer_with_decimal_pos(self):
        """Test formatting an integer with decimal position."""
        result = self.format(1234, ".", 2)
        self.assertEqual(result, "1234.00")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_zero(self):
        """Test formatting zero."""
        result = self.format(0, ".")
        self.assertEqual(result, "0")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_negative_integer(self):
        """Test formatting negative integer."""
        result = self.format(-1234, ".")
        self.assertEqual(result, "-1234")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_negative_with_decimal(self):
        """Test formatting negative number with decimals."""
        result = self.format(-1234.56, ".", 2)
        self.assertEqual(result, "-1234.56")

    # Test float formatting
    @ignore_warnings(category=DeprecationWarning)
    def test_format_float_basic(self):
        """Test formatting a basic float."""
        result = self.format(1234.567, ".", 2)
        self.assertEqual(result, "1234.56")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_float_truncation(self):
        """Test that extra decimal places are truncated."""
        result = self.format(1234.56789, ".", 2)
        self.assertEqual(result, "1234.56")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_float_round_down(self):
        """Test rounding down behavior."""
        result = self.format(1234.564, ".", 2)
        self.assertEqual(result, "1234.56")

    # Test Decimal formatting
    @ignore_warnings(category=DeprecationWarning)
    def test_format_decimal_basic(self):
        """Test formatting a Decimal object."""
        from decimal import Decimal
        result = self.format(Decimal("1234.56"), ".", 2)
        self.assertEqual(result, "1234.56")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_decimal_precision(self):
        """Test formatting Decimal with high precision."""
        from decimal import Decimal
        result = self.format(Decimal("1234.56789"), ".", 4)
        self.assertEqual(result, "1234.5678")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_decimal_very_small(self):
        """Test very small Decimal values become zero."""
        from decimal import Decimal
        result = self.format(Decimal("0.000001"), ".", 2)
        self.assertEqual(result, "0.00")

    # Test string number formatting
    @ignore_warnings(category=DeprecationWarning)
    def test_format_string_number(self):
        """Test formatting a string number."""
        result = self.format("1234", ".", 2)
        self.assertEqual(result, "1234.00")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_string_with_decimal(self):
        """Test formatting a string with decimal point."""
        result = self.format("1234.56", ".", 2)
        self.assertEqual(result, "1234.56")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_string_negative(self):
        """Test formatting a negative string number."""
        result = self.format("-1234", ".", 2)
        self.assertEqual(result, "-1234.00")

    # Test None and empty string handling
    @ignore_warnings(category=DeprecationWarning)
    def test_format_none_returns_marked_safe(self):
        """Test that None returns marked safe value."""
        from django.utils.safestring import SafeString
        result = self.format(None, ".")
        self.assertIsInstance(result, SafeString)
        self.assertIsNone(result)

    @ignore_warnings(category=DeprecationWarning)
    def test_format_empty_string_returns_marked_safe(self):
        """Test that empty string returns marked safe value."""
        from django.utils.safestring import SafeString
        result = self.format("", ".")
        self.assertIsInstance(result, SafeString)
        self.assertEqual(result, "")

    # Test thousand separator
    @override_settings(USE_L10N=True, USE_THOUSAND_SEPARATOR=True)
    @ignore_warnings(category=DeprecationWarning)
    def test_format_thousand_separator(self):
        """Test thousand separator insertion."""
        result = self.format(1234567, ",", 0, grouping=3, thousand_sep=",")
        self.assertEqual(result, "1,234,567")

    @override_settings(USE_L10N=True, USE_THOUSAND_SEPARATOR=True)
    @ignore_warnings(category=DeprecationWarning)
    def test_format_thousand_separator_space(self):
