    @override_settings(USE_L10N=True, USE_THOUSAND_SEPARATOR=True)
    @ignore_warnings(category=DeprecationWarning)
    def test_format_grouping_uniform(self):
        """Test uniform digit grouping."""
        result = self.format(1234567890, ".", 0, grouping=3, thousand_sep=",")
        self.assertEqual(result, "1,234,567,890")

    @override_settings(USE_L10N=True, USE_THOUSAND_SEPARATOR=True)
    @ignore_warnings(category=DeprecationWarning)
    def test_format_grouping_non_uniform(self):
        """Test non-uniform digit grouping sequence."""
        result = self.format(1234567890, ".", 0, grouping=(3, 2), thousand_sep=",")
        self.assertEqual(result, "1,23,45,67,890")

    @override_settings(USE_L10N=True, USE_THOUSAND_SEPARATOR=True)
    @ignore_warnings(category=DeprecationWarning)
    def test_format_grouping_zero(self):
        """Test no grouping when grouping is 0."""
        result = self.format(1234567, ".", 0, grouping=0, thousand_sep=",")
        self.assertEqual(result, "1234567")

    # Test force_grouping
    @override_settings(USE_L10N=False, USE_THOUSAND_SEPARATOR=False)
    @ignore_warnings(category=DeprecationWarning)
    def test_format_force_grouping_true(self):
        """Test force_grouping overrides settings."""
        result = self.format(1234567, ".", 0, grouping=3, thousand_sep=",", force_grouping=True)
        self.assertEqual(result, "1,234,567")

    @override_settings(USE_L10N=True, USE_THOUSAND_SEPARATOR=True)
    @ignore_warnings(category=DeprecationWarning)
    def test_format_force_grouping_false(self):
        """Test force_grouping=False disables grouping."""
        result = self.format(1234567, ".", 0, grouping=3, thousand_sep=",", force_grouping=False)
        self.assertEqual(result, "1234567")

    # Test decimal separator
    @ignore_warnings(category=DeprecationWarning)
    def test_format_decimal_separator_comma(self):
        """Test comma as decimal separator."""
        result = self.format(1234.56, ",", 2)
        self.assertEqual(result, "1234,56")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_decimal_separator_space(self):
        """Test space as decimal separator."""
        result = self.format(1234.56, " ", 2)
        self.assertEqual(result, "1234 56")

    # Test decimal_pos parameter
    @ignore_warnings(category=DeprecationWarning)
    def test_format_decimal_pos_zero(self):
        """Test decimal_pos=0 removes decimals."""
        result = self.format(1234.56, ".", 0)
        self.assertEqual(result, "1234")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_decimal_pos_more_digits(self):
        """Test adding zeros when decimal_pos > actual decimals."""
        result = self.format(1234.5, ".", 3)
        self.assertEqual(result, "1234.500")

    @ignore_warnings(category=DeprecationWarning)
    def test_format_decimal_pos_less_digits(self):
        """Test truncating when decimal_pos < actual decimals."""
        result = self.format(1234.56789, ".", 2)
        self.assertEqual(result, "1234.56")

    # Test scientific notation handling
    @patch('django.utils.numberformat.settings')
    def test_format_scientific_notation_large(self, mock_settings):
        """Test handling of very large numbers in scientific notation."""
        mock_settings.USE_L10N = False
        mock_settings.USE_THOUSAND_SEPARATOR = False
        result = self.format(1e200, ".", 0)
        self.assertIn("e", result.lower())

    @patch('django.utils.numberformat.settings')
    def test_format_scientific_notation_small(self, mock_settings):
