class MultiDecorateTests(SimpleTestCase):
    """Tests for _multi_decorate function."""

    def setUp(self):
        from django.utils.decorators import _multi_decorate
        self._multi_decorate = _multi_decorate

    def test_multi_decorate_single_decorator(self):
        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_decorated"
            return wrapper

        class MyClass:
            def my_method(self):
                return "original"

        decorated = self._multi_decorate(my_decorator, MyClass.my_method)
        obj = MyClass()
        result = decorated(obj)
        self.assertEqual(result, "original_decorated")

    def test_multi_decorate_multiple_decorators(self):
        def decorator1(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_1"
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_2"
            return wrapper

        class MyClass:
            def my_method(self):
                return "original"

        # Decorators are reversed in _multi_decorate, so decorator2 is applied first
        decorated = self._multi_decorate([decorator1, decorator2], MyClass.my_method)
        obj = MyClass()
        result = decorated(obj)
        self.assertEqual(result, "original_2_1")

    def test_multi_decorate_preserves_attributes(self):
        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            wrapper.custom_attr = "custom_value"
            return wrapper

        class MyClass:
            def my_method(self):
                return "original"

        decorated = self._multi_decorate(my_decorator, MyClass.my_method)
        # The wrapper should preserve attributes from the method being decorated
        self.assertTrue(hasattr(decorated, '__name__'))
        self.assertEqual(decorated.__name__, 'my_method')


