class IntegrationTests(SimpleTestCase):
    """Integration tests for the decorators module."""

    def test_full_decorator_chain(self):
        from django.utils.decorators import method_decorator, make_middleware_decorator

        # Test that method_decorator properly wraps a method with middleware
        class SimpleMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_request(self, request):
                # Return None to let the request continue
                return None

            def process_response(self, request, response):
                # Just return the response unchanged
                return response

        @method_decorator(make_middleware_decorator(SimpleMiddleware), name='my_method')
        class MyClass:
            def my_method(self, value):
                return f"processed_{value}"

        obj = MyClass()
        request = MagicMock()
        result = obj.my_method("test")
        self.assertEqual(result, "processed_test")

    def test_multiple_decorators_on_method(self):
        from django.utils.decorators import method_decorator

        def decorator1(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_1"
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs) + "_2"
            return wrapper

        @method_decorator([decorator1, decorator2], name='my_method')
        class MyClass:
            def my_method(self):
                return "original"

        obj = MyClass()
        result = obj.my_method()
        self.assertEqual(result, "original_2_1")

    def test_classonlymethod_with_inheritance(self):
        from django.utils.decorators import classonlymethod

        class Parent:
            @classonlymethod
            def parent_method(cls):
                return "parent"

        class Child(Parent):
            @classonlymethod
            def child_method(cls):
                return "child"

        self.assertEqual(Parent.parent_method(), "parent")
        self.assertEqual(Child.child_method(), "child")
        self.assertEqual(Child.parent_method(), "parent")

        child_obj = Child()
        with self.assertRaises(AttributeError):
            child_obj.child_method()

