    def test_has_contribute_to_class_bound_method(self):
        """Test _has_contribute_to_class with bound method."""
        from django.db.models.base import _has_contribute_to_class

        class TestClass:
            @classmethod
            def contribute_to_class(cls, model, name):
                pass

        self.assertFalse(_has_contribute_to_class(TestClass.contribute_to_class))

        obj = TestClass()
        # Bound methods have contribute_to_class attribute
        self.assertTrue(hasattr(obj, 'contribute_to_class'))
        result = _has_contribute_to_class(obj)
        # Since obj is an instance (not a class), it should check for the method
        self.assertFalse(result)  # Instance itself doesn't have contribute_to_class

    def test_has_contribute_to_class_class(self):
        """Test _has_contribute_to_class with class."""
        from django.db.models.base import _has_contribute_to_class

        class TestClass:
            def contribute_to_class(self, cls, name):
                pass

        self.assertFalse(_has_contribute_to_class(TestClass))


