from django.template.defaultfilters import join
from django.test import SimpleTestCase
from django.utils.safestring import mark_safe

from ..utils import setup


class JoinTests(SimpleTestCase):
    @setup({"join01": "{{ a|join:', ' }} {{ b|join:', ' }}"})
    def test_join01(self):
        output = self.engine.render_to_string(
            "join01", {"a": ["a&b", "x"], "b": [mark_safe("a&b"), "x"]}
        )
        self.assertEqual(output, "a&amp;b, x a&b, x")

    @setup(
        {
            "join02": (
                "{% autoescape off %}{{ a|join:', ' }} {{ b|join:', ' }}{% endautoescape %}"
            )
        }
    )
    def test_join02(self):
        output = self.engine.render_to_string(
            "join02", {"a": ["a&b", "x"], "b": [mark_safe("a&b"), "x"]}
        )
        self.assertEqual(output, "a&b, x a&b, x")

    @setup({"join03": "{{ a|join:'-' }}"})
    def test_join03(self):
        output = self.engine.render_to_string("join03", {"a": ["a", "b", "c"]})
        self.assertEqual(output, "a-b-c")

    @setup({"join04": "{{ a|join:'' }}"})
    def test_join04(self):
        output = self.engine.render_to_string("join04", {"a": ["a", "b", "c"]})
        self.assertEqual(output, "abc")

    @setup({"join05": "{{ a|join:' | ' }}"})
    def test_join05(self):
        output = self.engine.render_to_string("join05", {"a": ["a", "b", "c"]})
        self.assertEqual(output, "a | b | c")

    @setup({"empty_list": "{{ a|join:',' }}"})
    def test_empty_list(self):
        output = self.engine.render_to_string("empty_list", {"a": []})
        self.assertEqual(output, "")

    @setup({"single_item": "{{ a|join:',' }}"})
    def test_single_item(self):
        output = self.engine.render_to_string("single_item", {"a": ["only"]})
        self.assertEqual(output, "only")


class FunctionTests(SimpleTestCase):
    def setUp(self):
        from django.template.defaultfilters import join as join_filter
        self.join_filter = join_filter

    def test_basic_join(self):
        result = self.join_filter(["a", "b", "c"], ", ")
        self.assertEqual(result, "a, b, c")

    def test_join_with_empty_separator(self):
        result = self.join_filter(["a", "b", "c"], "")
        self.assertEqual(result, "abc")

    def test_join_with_special_chars(self):
        result = self.join_filter(["a&b", "c<d"], "|")
        self.assertIn("&amp;", result)
        self.assertIn("&lt;", result)

    def test_join_with_numbers(self):
        result = self.join_filter([1, 2, 3], "-")
        self.assertEqual(result, "1-2-3")

    def test_join_with_mixed_types(self):
        result = self.join_filter([1, "two", 3.0], " ")
        self.assertEqual(result, "1 two 3.0")

    def test_join_empty_list(self):
        result = self.join_filter([], ",")
        self.assertEqual(result, "")

    def test_join_single_item(self):
        result = self.join_filter(["only"], ",")
        self.assertEqual(result, "only")


    def test_join_none_arg_fails_silently(self):
        """Test that TypeError is handled when arg isn't iterable."""
        # When arg is None, str(None).join() works fine
        result = self.join_filter(["a", "b"], None)
        self.assertEqual(result, "aNoneb")

        # Test with an object that truly can't be joined
        class BadJoiner:
            def __str__(self):
                return 'bad'
            def join(self, iterable):
                raise TypeError('Cannot join')

        result = self.join_filter(["a", "b"], BadJoiner())
        # The conditional_escape wraps the BadJoiner, so str(BadJoiner()).join() is used
        self.assertEqual(result, "abadb")

    def test_join_with_unicode(self):
        result = self.join_filter(["α", "β", "γ"], " ")
        self.assertEqual(result, "α β γ")

    def test_join_with_newlines(self):
        result = self.join_filter(["line1\n", "line2\n"], "\n")
        self.assertEqual(result, "line1\n\nline2\n")

    def test_join_with_html_content(self):
        result = self.join_filter(["<script>", "</script>"], " ")
        self.assertIn("&lt;script&gt;", result)
        self.assertIn("&lt;/script&gt;", result)

    def test_join_with_mark_safe_input(self):
        safe_items = [mark_safe("<b>bold</b>"), mark_safe("<i>italic</i>")]
        result = self.join_filter(safe_items, " ")
        self.assertIn("<b>bold</b>", result)

    def test_join_autoescape_off(self):
        from django.template import Template, Context
        template = Template("{% autoescape off %}{{ items|join:',' }}{% endautoescape %}")
        context = Context({"items": ["<b>bold</b>", "<i>italic</i>"]})
        result = template.render(context)
        self.assertEqual(result, "<b>bold</b>,<i>italic</i>")

    def test_join_with_boolean_values(self):
        result = self.join_filter([True, False, True], " ")
        self.assertEqual(result, "True False True")

    def test_join_with_zero_values(self):
        result = self.join_filter([0, 0, 0], "+")
        self.assertEqual(result, "0+0+0")

    def test_join_with_negative_numbers(self):
        result = self.join_filter([-1, -2, -3], ",")
        self.assertEqual(result, "-1,-2,-3")

    def test_join_with_float_values(self):
        result = self.join_filter([1.5, 2.7, 3.14], " ")
        self.assertEqual(result, "1.5 2.7 3.14")

    def test_join_with_none_in_list(self):
        result = self.join_filter(["a", None, "c"], ",")
        self.assertEqual(result, "a,None,c")

    def test_join_with_empty_strings(self):
        result = self.join_filter(["", "a", "", "b"], "|")
        self.assertEqual(result, "|a||b")

    def test_join_with_whitespace(self):
        result = self.join_filter([" a ", " b ", " c "], "-")
        self.assertEqual(result, " a - b - c ")

    def test_join_with_tuples(self):
        result = self.join_filter(("x", "y", "z"), "_")
        self.assertEqual(result, "x_y_z")

    def test_join_with_generator(self):
        gen = (str(i) for i in range(3))
        result = self.join_filter(gen, ",")
        self.assertEqual(result, "0,1,2")


    def test_join_with_nested_lists(self):
        result = self.join_filter([["a", "b"], ["c", "d"]], ",")
        # Nested lists are converted to strings with HTML escaping
        self.assertIn("a", result)
        self.assertIn("b", result)
        self.assertIn("c", result)
        self.assertIn("d", result)

    def test_join_with_dict_keys(self):
        d = {"a": 1, "b": 2, "c": 3}
        result = self.join_filter(d.keys(), ",")
        self.assertEqual(result, "a,b,c")

    def test_join_with_dict_values(self):
        d = {"a": 1, "b": 2, "c": 3}
        result = self.join_filter(d.values(), ",")
        self.assertEqual(result, "1,2,3")

    def test_join_with_large_list(self):
        large_list = list(range(1000))
        result = self.join_filter(large_list, ",")
        expected = ",".join(str(i) for i in range(1000))
        self.assertEqual(result, expected)

    def test_join_with_very_long_separator(self):
        separator = "x" * 100
        result = self.join_filter(["a", "b"], separator)
        self.assertEqual(result, f"a{separator}b")

    def test_join_with_special_separators(self):
        separators = [
            ("|", "a|b"),
            ("\\", "a\\b"),
            ("/", "a/b"),
            ("@", "a@b"),
            ("#", "a#b"),
        ]
        for sep, expected in separators:
            result = self.join_filter(["a", "b"], sep)
            self.assertEqual(result, expected)

    def test_join_with_mark_safe_separator(self):
        result = self.join_filter(["a", "b"], mark_safe("-"))
        self.assertIn("a-b", result)

    def test_join_with_complex_objects(self):
        class TestObj:
            def __str__(self):
                return "test"

        obj = TestObj()
        result = self.join_filter([obj, obj], ",")
        self.assertEqual(result, "test,test")

    def test_join_with_exception_handling(self):
        """Test that invalid arguments fail silently."""
        class BadArg:
            def __iter__(self):
                raise ValueError("Cannot iterate")

        result = self.join_filter(["a", "b"], BadArg())
        # Should handle gracefully
        self.assertIsNotNone(result)

