class TestWrapInPandasContainer:
    """Tests for _wrap_in_pandas_container function."""

    def setup_method(self):
        """Setup test fixtures."""
        np.random.seed(42)
        self.dense_data = np.array([[1, 2, 3], [4, 5, 6]])
        self.sparse_data = sparse.csr_matrix(self.dense_data)

    def test_wrap_dense_ndarray(self):
        """Test wrapping dense ndarray creates DataFrame."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        result = _wrap_in_pandas_container(
            self.dense_data, columns=["a", "b", "c"], index=[0, 1]
        )
        assert hasattr(result, "columns")
        assert hasattr(result, "index")
        assert list(result.columns) == ["a", "b", "c"]
        assert list(result.index) == [0, 1]

    def test_wrap_sparse_raises_value_error(self):
        """Test wrapping sparse data raises ValueError."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        with pytest.raises(ValueError, match="Pandas output does not support sparse data"):
            _wrap_in_pandas_container(self.sparse_data, columns=["a", "b", "c"])

    def test_wrap_callable_columns_success(self):
        """Test wrapping with callable columns that succeeds."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        def get_columns():
            return ["x", "y", "z"]

        result = _wrap_in_pandas_container(self.dense_data, columns=get_columns)
        assert list(result.columns) == ["x", "y", "z"]

    def test_wrap_callable_columns_raises_falls_back_to_none(self):
        """Test wrapping with callable columns that raises falls back to None."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        def failing_columns():
            raise RuntimeError("Failed")

        result = _wrap_in_pandas_container(self.dense_data, columns=failing_columns)
        # Should use default column names
        assert hasattr(result, "columns")

    def test_wrap_existing_dataframe_changes_columns(self):
        """Test wrapping existing DataFrame changes columns inplace."""
        import pandas as pd

        from sklearn.utils._set_output import _wrap_in_pandas_container

        df = pd.DataFrame(self.dense_data, columns=["old1", "old2", "old3"])
        result = _wrap_in_pandas_container(df, columns=["new1", "new2", "new3"])
        assert list(result.columns) == ["new1", "new2", "new3"]
        assert result is df  # Should be same object

    def test_wrap_existing_dataframe_ignores_columns_none(self):
        """Test wrapping existing DataFrame with columns=None keeps original."""
        import pandas as pd

        from sklearn.utils._set_output import _wrap_in_pandas_container

        df = pd.DataFrame(self.dense_data, columns=["old1", "old2", "old3"])
        result = _wrap_in_pandas_container(df, columns=None)
        assert list(result.columns) == ["old1", "old2", "old3"]

    def test_wrap_ndarray_with_none_columns(self):
        """Test wrapping ndarray with columns=None uses range."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        result = _wrap_in_pandas_container(self.dense_data, columns=None)
        assert list(result.columns) == [0, 1, 2]


