class TestIntegration:
    """Integration tests for the full set_output functionality."""

    def setup_method(self):
        """Setup test fixtures."""
        np.random.seed(42)
        self.X = np.random.randn(10, 5)

    def test_full_pipeline_with_pandas_output(self):
        """Test full pipeline with pandas output."""

        class PipelineEstimator(_SetOutputMixin, auto_wrap_output_keys=("transform",)):
            def __init__(self, n_features=5):
                self.n_features = n_features

            def fit(self, X, y=None):
                return self

            def transform(self, X):
                return X * 2 + 1

            def get_feature_names_out(self):
                return [f"f{i}" for i in range(self.n_features)]

        estimator = PipelineEstimator()
        estimator.fit(self.X)
        estimator.set_output(transform="pandas")

        result = estimator.transform(self.X)
        import pandas as pd

        assert isinstance(result, pd.DataFrame)
        assert list(result.columns) == ["f0", "f1", "f2", "f3", "f4"]

    def test_full_pipeline_default_output(self):
        """Test full pipeline with default output."""

        class PipelineEstimator(_SetOutputMixin, auto_wrap_output_keys=("transform",)):
            def __init__(self, n_features=5):
                self.n_features = n_features

            def fit(self, X, y=None):
                return self

            def transform(self, X):
                return X * 2 + 1

            def get_feature_names_out(self):
                return [f"f{i}" for i in range(self.n_features)]

        estimator = PipelineEstimator()
        estimator.fit(self.X)

        result = estimator.transform(self.X)
        assert isinstance(result, np.ndarray)

    def test_set_output_chaining(self):
        """Test set_output chaining works."""

        class PipelineEstimator(_SetOutputMixin, auto_wrap_output_keys=("transform",)):
            def __init__(self, n_features=5):
                self.n_features = n_features

            def fit(self, X, y=None):
                return self

            def transform(self, X):
                return X * 2 + 1

            def get_feature_names_out(self):
                return [f"f{i}" for i in range(self.n_features)]

        estimator = PipelineEstimator()
        estimator.fit(self.X)

        # Chain set_output calls
        estimator.set_output(transform="pandas").set_output(transform="default")

        result = estimator.transform(self.X)
        assert isinstance(result, np.ndarray)

    def test_fit_transform_with_pandas_output(self):
        """Test fit_transform with pandas output."""

        class PipelineEstimator(_SetOutputMixin, auto_wrap_output_keys=("transform",)):
            def __init__(self, n_features=5):
                self.n_features = n_features

            def fit(self, X, y=None):
                return self

            def transform(self, X):
                return X * 2 + 1

            def fit_transform(self, X, y=None):
                self.fit(X, y)
                return self.transform(X)

            def get_feature_names_out(self):
                return [f"f{i}" for i in range(self.n_features)]

        estimator = PipelineEstimator()
        estimator.set_output(transform="pandas")

        result = estimator.fit_transform(self.X)
        import pandas as pd

        assert isinstance(result, pd.DataFrame)

