class QuoteUnquoteTests(SimpleTestCase):
    """Tests for quote() and unquote() functions."""

    def test_quote_simple_string(self):
        from django.contrib.admin.utils import quote
        result = quote("simple")
        self.assertEqual(result, "simple")

    def test_quote_slash(self):
        from django.contrib.admin.utils import quote
        result = quote("a/b")
        self.assertEqual(result, "a_2Fb")

    def test_quote_underscore(self):
        from django.contrib.admin.utils import quote
        result = quote("a_b")
        self.assertEqual(result, "a_5Fb")

    def test_quote_colon(self):
        from django.contrib.admin.utils import quote
        result = quote("a:b")
        self.assertEqual(result, "a_3Ab")

    def test_quote_special_chars(self):
        from django.contrib.admin.utils import quote
        result = quote('":/_#?;@&=+$,"[]<>%\n\\')
        expected = '_%02A_%022_%02F_%05F_%023_%03F_%03B_%040_%026_%03D_%02B_%024_%02C_%022_%05B_%05D_%03C_%03E_%025_%0AN_%05C'
        self.assertEqual(result, expected)

    def test_quote_non_string_returns_same(self):
        from django.contrib.admin.utils import quote
        result = quote(123)
        self.assertEqual(result, 123)

    def test_unquote_simple_string(self):
        from django.contrib.admin.utils import unquote
        result = unquote("simple")
        self.assertEqual(result, "simple")

    def test_unquote_encoded_slash(self):
        from django.contrib.admin.utils import unquote
        result = unquote("a_2Fb")
        self.assertEqual(result, "a/b")

    def test_unquote_encoded_underscore(self):
        from django.contrib.admin.utils import unquote
        result = unquote("a_5Fb")
        self.assertEqual(result, "a_b")

    def test_unquote_roundtrip(self):
        from django.contrib.admin.utils import quote, unquote
        original = "test/path:value"
        quoted = quote(original)
        unquoted = unquote(quoted)
        self.assertEqual(unquoted, original)


