class TestUrlQuote(TestCase):
    def setUp(self):
        from django.utils.http import urlquote
        self.urlquote = urlquote

    def test_urlquote_basic(self):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            result = self.urlquote('/hello world/')
        self.assertEqual(result, '/hello%20world/')

    def test_urlquote_with_safe(self):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            result = self.urlquote('/hello world/', safe='/')
        self.assertEqual(result, '/hello%20world/')

    def test_urlquote_empty_string(self):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            result = self.urlquote('')
        self.assertEqual(result, '')

    def test_urlquote_special_chars(self):
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            result = self.urlquote('a+b=c')
        # Both + and = should be percent-encoded
        self.assertIn('%2B', result)
        self.assertIn('%3D', result)


