class TestUrlEncode(TestCase):
    def setUp(self):
        from django.utils.http import urlencode
        self.urlencode = urlencode

    def test_urlencode_dict(self):
        query = {'key': 'value'}
        result = self.urlencode(query)
        self.assertIn('key=value', result)

    def test_urlencode_multivaluedict(self):
        mvd = MultiValueDict({'key': ['value1', 'value2']})
        result = self.urlencode(mvd, doseq=True)
        self.assertIn('key=value1', result)
        self.assertIn('key=value2', result)

    def test_urlencode_none_value_raises_typeerror(self):
        with self.assertRaises(TypeError):
            self.urlencode({'key': None})

    def test_urlencode_list_values(self):
        query = {'key': ['val1', 'val2']}
        result = self.urlencode(query, doseq=True)
        self.assertIn('key=val1', result)
        self.assertIn('key=val2', result)

    def test_urlencode_generator_values(self):
        def gen():
            yield 'val1'
            yield 'val2'
        query = {'key': gen()}
        result = self.urlencode(query, doseq=True)
        self.assertIn('key=val1', result)
        self.assertIn('key=val2', result)

    def test_urlencode_none_in_generator_raises_typeerror(self):
        def gen():
            yield 'val1'
            yield None
        query = {'key': gen()}
        with self.assertRaises(TypeError):
            self.urlencode(query, doseq=True)


